import { Opcode, Frame } from './frame';

/**
 * The `PLPL` network batch codec — the TypeScript mirror of the Java
 * `com.pathland.view.transport.FrameCodec` and the Rust `pathland_core_transport`.
 *
 * Batch wire format (both directions share the header):
 *
 * ```
 * magic "PLPL" (u32 LE) | version (u16) | flags (u16) | frameCount (u32)
 * | opcodeCount (u32) | opcodes (16 B × count) | stringsLen (u32) | string bytes
 * ```
 *
 * Frames are self-contained: `SET_TEXT` / STRING-valued `SET_PROPERTY` reference
 * entries in the batch's own string section by *relative* offset.
 */
export const BATCH_MAGIC = 0x504c_504c; // "PLPL"
export const BATCH_VERSION = 1;
export const HOST_TO_GUEST = 0x0001;
export const HEADER_BYTES = 16;

const encoder = new TextEncoder();
const decoder = new TextDecoder();

/** Decode a `PLPL` batch into a frame (opcodes + string section). */
export function decodeFrame(bytes: Uint8Array): Frame {
  if (bytes.byteLength < HEADER_BYTES) {
    throw new Error('batch truncated');
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);

package com.pathland.view;

/** Opcode categories (mirrors {@code pathland_core::category}). */
public final class Categories {

    public static final int TREE = 0x01;
    public static final int STYLE = 0x02;
    public static final int EVENT = 0x03;
    public static final int META = 0x04;

    private Categories() {}
}package com.pathland.view;

/** Protocol property ids (mirrors {@code pathland_core::property_id}). */
public final class Properties {

    // Stack
    public static final int SPACING = 0x0001;
    public static final int ALIGNMENT = 0x0002;
    public static final int CONTENT_MARGINS = 0x0005;
    // Text
    public static final int TEXT = 0x000A;
    public static final int LINE_LIMIT = 0x000B;
    public static final int TEXT_ALIGNMENT = 0x000C;
    public static final int TRUNCATION_MODE = 0x000D;
    // Style (0x1000 range)
    public static final int BACKGROUND_COLOR = 0x1001;
    public static final int BORDER_WIDTH = 0x1003;
    public static final int BORDER_COLOR = 0x1004;
    public static final int BORDER_RADIUS = 0x1005;
    public static final int PADDING_STYLE = 0x1006;
    public static final int FONT_SIZE = 0x1007;
    public static final int FONT_WEIGHT = 0x1008;
    public static final int FONT_FAMILY = 0x1009;
    public static final int COLOR = 0x100A;
    public static final int WIDTH = 0x100B;
    public static final int HEIGHT = 0x100C;
    public static final int OPACITY = 0x100D;
    public static final int VISIBLE = 0x100E;
    public static final int Z_INDEX = 0x100F;
    public static final int CLIPS_TO_BOUNDS = 0x1010;
    public static final int PADDING = 0x1011;
    public static final int PADDING_TOP = 0x1012;
    public static final int PADDING_RIGHT = 0x1013;
    public static final int PADDING_BOTTOM = 0x1014;
    public static final int PADDING_LEFT = 0x1015;
    public static final int BORDER_EDGES = 0x1016;
    // Semantic (0x2000 range)
    public static final int ROLE = 0x2001;
    public static final int STATE = 0x2002;
    public static final int ENABLED = 0x2003;
    public static final int SELECTED = 0x2004;
    public static final int EVENT_LISTENERS = 0x2005;
    public static final int VALUE = 0x2006;
    public static final int MIN_VALUE = 0x2007;
    public static final int MAX_VALUE = 0x2008;
    public static final int LABEL = 0x200A;
    public static final int PROMPT = 0x200B;

    private Properties() {}
}package com.pathland.view;

/** Value types for {@code STYLE::SET_PROPERTY} (mirrors {@code pathland_core::value_type}). */
public final class ValueTypes {

    public static final int U8 = 0x01;
    public static final int U32 = 0x02;
    public static final int I32 = 0x03;
    public static final int F32 = 0x04;
    public static final int STRING = 0x05;
    public static final int ENUM = 0x06;
    public static final int COLOR = 0x07;
    public static final int DESIGN_TOKEN = 0x08;

    /** The protocol value type for a property id (mirrors {@code value_type_for}). */
    public static int forProperty(int prop) {
        return switch (prop) {
            case Properties.COLOR, Properties.BACKGROUND_COLOR, Properties.BORDER_COLOR -> COLOR;
            case Properties.EVENT_LISTENERS, Properties.BORDER_EDGES -> U32;
            case Properties.SELECTED -> U8;
            case Properties.LABEL, Properties.PROMPT, Properties.FONT_FAMILY -> STRING;
            default -> F32;
        };
    }

    private ValueTypes() {}
}

