    header: &mut [u8],
    cursor_off: usize,
    bytes: &[u8],
) -> Result<u32, ArenaError> {
    let cursor = header::get_u32(header, cursor_off) as usize;
    let len = bytes.len();
    let needed = 4 + len;
    if cursor + needed > data.len() {
