    if let Some(bits) = node.properties.get(&property_id::FONT_WEIGHT) { css.push_str(&format!("font-weight:{v};")); }
    if let Some(s) = node.strings.get(&property_id::FONT_FAMILY) { css.push_str(&format!("font-family:'{}';", s.replace('\'', "\\'"))); }
    if let Some(bits) = node.properties.get(&property_id::OPACITY) { css.push_str(&format!("opacity:{v};")); }
