        node.properties.insert(property_id::POSITION_Y, self.y.to_bits());
    }
}

impl ViewModifier for ZIndex {
    fn apply(&self, node: &mut Node) {
        node.properties.insert(property_id::Z_INDEX, self.0.to_bits());
    }
}

