package com.pathland.demo;

import com.pathland.view.Alignment;
import com.pathland.view.Color;
import com.pathland.view.Commands;
import com.pathland.view.FontWeight;
import com.pathland.view.View;

/**
 * A reusable kitchen-sink section card: a titled, bordered, rounded container that
 * hosts one section's controls. Demonstrates composition — a custom {@code View}
 * wrapping arbitrary content with style modifiers.
 */
public final class SectionCard implements View {

    private static final Color TITLE_COLOR = Color.rgb(0x55, 0x64, 0x6D);
    private static final Color BORDER = Color.rgb(0xE2, 0xE8, 0xF0);

    private final String title;
    private final View content;

    public SectionCard(String title, View content) {
        this.title = title;
        this.content = content;
    }

    @Override
    public View body() {
        return View.vstack(
                View.text(title).fontSize(14).fontWeight(FontWeight.SEMIBOLD).foregroundStyle(TITLE_COLOR),
                View.divider().padding(0, 0, 8, 0),
                content
        ).padding(16)
                .background(Color.WHITE)
                .border(1, BORDER, 10)
                .cornerRadius(10)
                .frame(Commands.Size.FILL, Float.NaN, Alignment.FILL);
    }
}

package com.pathland.demo;

import com.pathland.view.Color;
import com.pathland.view.FontWeight;
import com.pathland.view.View;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;
import com.pathland.view.state.State;

/**
 * Counter section: a persisted {@code State<Integer>} mutated by buttons and a
 * {@code Stepper} that sizes the increment step. Demonstrates {@code Button},
 * {@code Stepper}, and a computed label.
 */
public final class CounterSection implements View {

    State<Integer> count = new State<>(0, "count");
    State<Integer> step = new State<>(1, "step");
    Signal<String> countLabel = Signals.computed(() -> "Count: " + count.get());

    @Override
    public View body() {
        return new SectionCard("Counter · State + Button + Stepper",
                View.vstack(
                        View.text(countLabel).fontSize(28).fontWeight(FontWeight.BOLD),
                        View.hstack(
                                View.button("−", () -> count.update(v -> v - step.get())),
                                View.button("+", () -> count.update(v -> v + step.get())),
                                View.button("Reset", () -> count.set(0))
                        ).padding(4),
                        View.text("Step size").foregroundStyle(Color.rgb(0x88, 0x88, 0x88)),
                        View.stepper(step.get(), 1, 10, 1, step.signal())
                ).padding(4)
        );
    }
}

