export function pickerStyle(node: PathlandNode): 'menu' | 'segmented' | 'wheel' | 'radioGroup' {
  const wire = node.f32(PROPERTY.PICKER_STYLE);
  switch (wire === undefined ? 0 : Math.round(wire)) {
