          [background]="m.background!"
          [border]="m.border!"
          [rounding]="m.rounding!"
          [opacity]="m.opacity!"
          [frame]="m.frame!"
          [flex]="m.flex!">
        </ui-image>
      }
      @default {
        @for (child of n.children(); track child) {
          <pathland-node [nodeId]="child" />
        }
      }
    }
  }
}

