package com.pathland.spring;

import org.springframework.web.socket.BinaryMessage;
import org.springframework.web.socket.CloseStatus;
import org.springframework.web.socket.WebSocketMessage;
import org.springframework.web.socket.WebSocketSession;
import org.springframework.web.socket.handler.AbstractWebSocketHandler;

import java.nio.ByteBuffer;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The live-updates WebSocket endpoint (Spring's counterpart to the Quarkus
 * {@code PathlandSocket}). Sessions are 1:1; the session id rides the {@code session}
 * cookie set on the SSR page. The id is resolved <strong>once per connection</strong>
 * and memoized, so every message (events, close) routes to the same session even when
 * the cookie is absent (e.g. an Angular client with no SSR visit).
 */
public class PathlandSocket extends AbstractWebSocketHandler {

    private final PathlandService service;
    private final Map<WebSocketSession, String> sessionIds = new ConcurrentHashMap<>();

    public PathlandSocket(PathlandService service) {
        this.service = service;
    }

    @Override
    public void afterConnectionEstablished(WebSocketSession session) {
        String id = resolveSessionId(session);
        sessionIds.put(session, id);
        service.open(id, session);
    }

    @Override
    public void handleMessage(WebSocketSession session, WebSocketMessage<?> message) {
        if (message instanceof BinaryMessage binary) {
            service.dispatch(sessionId(session), toByteArray(binary.getPayload()));
        }
    }

    @Override
    public void afterConnectionClosed(WebSocketSession session, CloseStatus status) {
        close(session);
    }

    @Override
    public void handleTransportError(WebSocketSession session, Throwable exception) {
        close(session);
    }

    private void close(WebSocketSession session) {
        String id = sessionIds.remove(session);
        if (id != null) {
            service.close(id);
        }
    }

    /** The memoized session id for the connection (falling back to a fresh resolve). */
    private String sessionId(WebSocketSession session) {
        String id = sessionIds.get(session);
        if (id == null) {
            id = resolveSessionId(session);
            sessionIds.put(session, id);
        }
        return id;
    }

    /** The session id from the {@code session} cookie (case-insensitive), else a fresh id. */
    private String resolveSessionId(WebSocketSession session) {
        for (Map.Entry<String, List<String>> header : session.getHandshakeHeaders().entrySet()) {
            if (!"cookie".equalsIgnoreCase(header.getKey())) {
                continue;
            }
            for (String value : header.getValue()) {
                for (String part : value.split(";")) {
                    String[] kv = part.trim().split("=", 2);
                    if (kv.length == 2
                            && "session".equalsIgnoreCase(kv[0].trim())
                            && !kv[1].isBlank()) {
                        return kv[1].trim();
                    }
                }
            }
        }
        return UUID.randomUUID().toString();
    }

    /** Copy a {@link ByteBuffer} into a {@code byte[]} regardless of backing array. */
    private static byte[] toByteArray(ByteBuffer buffer) {
        ByteBuffer duplicate = buffer.duplicate();
        byte[] bytes = new byte[duplicate.remaining()];
        duplicate.get(bytes);
        return bytes;
    }
}

package com.pathland.quarkus;

import io.quarkus.arc.Arc;
import io.quarkus.arc.ClientProxy;
import io.quarkus.websockets.next.OnBinaryMessage;
import io.quarkus.websockets.next.OnClose;
import io.quarkus.websockets.next.OnOpen;
import io.quarkus.websockets.next.WebSocket;
import io.quarkus.websockets.next.WebSocketConnection;
import jakarta.inject.Inject;

import java.util.UUID;

/**
 * The live-updates WebSocket endpoint. Sessions are <strong>1:1</strong>: the session id
 * is carried by the {@code session} cookie set on the SSR page (the browser sends it
 * automatically on the handshake), and each connection owns its own {@link SessionApp}.
 * The id is resolved <strong>once per connection</strong> (this endpoint bean is
 * connection-scoped) and memoized, so every message — events and close — routes to the
 * same session even when the cookie is absent (e.g. an Angular client with no SSR visit).
 */
@WebSocket(path = "/ws")
public class PathlandSocket {

    @Inject
    WebSocketConnection connection;

    @Inject
    PathlandApp app;

    private volatile String sessionId;

    @OnOpen
    void open() {
        // Resolve the concrete connection while the session context is active: the CDI
        // bean is session-scoped, so its client proxy would fail off-thread. ClientProxy
        // unwraps it to the real WebSocketConnectionBase, whose send methods work from
        // any thread.
        WebSocketConnection resolved =
                ClientProxy.unwrap(Arc.container().instance(WebSocketConnection.class).get());
        app.open(sessionId(), resolved);
    }

    @OnClose
    void close() {
        app.close(sessionId());
    }

    @OnBinaryMessage
    void onBinary(byte[] message) {
        app.dispatch(sessionId(), message);
    }

    /** The per-connection session id: the {@code session} cookie, or a fresh id memoized once. */
    private String sessionId() {
        String current = sessionId;
        if (current == null) {
            synchronized (this) {
                current = sessionId;
                if (current == null) {
                    current = resolveSessionId();
                    sessionId = current;
                }
            }
        }
        return current;
    }

    /** The session id from the {@code session} cookie (case-insensitive), else a fresh id. */
    private String resolveSessionId() {
        String cookie = connection.handshakeRequest().header("Cookie");
        if (cookie != null) {
            for (String part : cookie.split(";")) {
                String[] kv = part.trim().split("=", 2);
                if (kv.length == 2 && "session".equalsIgnoreCase(kv[0].trim()) && !kv[1].isBlank()) {
                    return kv[1].trim();
                }
            }
        }
        return UUID.randomUUID().toString();
    }
}

