package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/**
 * A rounded rectangle shape (a {@code SHAPE} node with
 * {@code SHAPE_KIND = RoundedRectangle} and {@code BORDER_RADIUS} = corner radius).
 */
public final class RoundedRectangle implements View {

    private final float cornerRadius;

    private RoundedRectangle(float cornerRadius) {
        this.cornerRadius = cornerRadius;
    }

    /** A rounded rectangle with a corner radius. */
    public static RoundedRectangle of(float cornerRadius) {
        return new RoundedRectangle(cornerRadius);
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.SHAPE);
        node.properties.put(Properties.SHAPE_KIND, (float) ShapeKind.ROUNDED_RECTANGLE.wire());
        node.properties.put(Properties.BORDER_RADIUS, cornerRadius);
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/** A vector geometry by {@link ShapeKind} (a {@code SHAPE} node). */
public final class Shape implements View {

    private final ShapeKind kind;

    private Shape(ShapeKind kind) {
        this.kind = kind;
    }

    /** A shape of the given kind (e.g. {@code Shape.of(ShapeKind.PATH)}). */
    public static Shape of(ShapeKind kind) {
        return new Shape(kind);
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.SHAPE);
        node.properties.put(Properties.SHAPE_KIND, (float) kind.wire());
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

import java.util.List;

/**
 * A transparent container that composites its children (SwiftUI {@code Group}). Today
 * it materializes as a {@code VSTACK} container node with no spacing/alignment — the
 * grouping itself carries no layout. A future protocol component may let it splice
 * children directly into the parent.
 */
public final class Group implements View {

    private final List<View> children;

    private Group(View... children) {
        this.children = List.of(children);
    }

    /** A group of child views. */
    public static Group of(View... children) {
        return new Group(children);
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.VSTACK);
        for (View child : children) {
            node.children.add(child.render(env));
        }
        return node;
    }
}

