import pathlib

OUT = pathlib.Path("/Users/michael/Development/michaelkrog/Pathland/lib/java/pathland-view/src/main/java/com/pathland/view")

def header(name, doc):
    return (f"package com.pathland.view;

"
            f"/**
 * {doc}
 */
"
            f"public final class {name} implements ViewModifier {{
")

def props(*lines):
    if len(lines) == 1:
        return "        return Modified.props(content, " + lines[0] + ");
"
    inner = ",
".join("                " + l for l in lines)
    return "        return Modified.props(content,
" + inner + ");
"

def write(name, doc, body_code):
    src = header(name, doc) + body_code + "}
"
    (OUT / f"{name}.java").write_text(src)

# ---- single F32 property helpers ----
def f32_simple(name, doc, prop, of_name="of"):
    write(name, doc,
        f"    private final float value;

"
        f"    private {name}(float value) {{
        this.value = value;
    }}

"
        f"    public static {name} {of_name}(float value) {{
        return new {name}(value);
    }}

"
        f"    @Override
    public View body(View content) {{
"
        + props(f"Modified.prop(Properties.{prop}, value)") + "    }
")

f32_simple("Opacity", "opacity ({@code 0..1}).", "OPACITY")
f32_simple("FontWidth", "font width (0.5–1.5, 1.0 default).", "FONT_WIDTH")
f32_simple("Kerning", "per-glyph kerning in points.", "KERNING")
f32_simple("Tracking", "uniform letter spacing in points.", "TRACKING")
f32_simple("BaselineOffset", "baseline offset in points.", "BASELINE_OFFSET")
f32_simple("LineSpacing", "line spacing in points.", "LINE_SPACING")
f32_simple("LayoutPriority", "layout priority for stretching/shrinking.", "LAYOUT_PRIORITY")
f32_simple("ZIndex", "draw-order elevation within a stack.", "Z_INDEX")
f32_simple("MinimumScaleFactor", "minimum scale factor for text shrinking.", "MINIMUM_SCALE_FACTOR")
f32_simple("CornerRadius", "corner radius ({@code BORDER_RADIUS}).", "BORDER_RADIUS")
f32_simple("Blur", "Gaussian blur radius.", "BLUR_RADIUS")
f32_simple("Saturation", "saturation filter ({@code 0..1}).", "SATURATION")
f32_simple("Contrast", "contrast filter ({@code 0..1}).", "CONTRAST")
f32_simple("Brightness", "brightness filter ({@code -1..1}).", "BRIGHTNESS")
f32_simple("Grayscale", "grayscale filter ({@code 0..1}).", "GRAYSCALE")
f32_simple("HueRotation", "hue rotation in degrees.", "HUE_ROTATION")
f32_simple("Rotation", "rotation after layout, in degrees (counter-clockwise).", "ROTATION_DEGREES")
f32_simple("ScaleEffect", "uniform scale after layout.", "SCALE")

# ---- U8 0/1 helpers ----
def u8_simple(name, doc, prop, value_expr, ofs):
    fields = f"    private final boolean on;

    private {name}(boolean on) {{
        this.on = on;
    }}

"
    body = props(f"Modified.prop(Properties.{prop}, {value_expr})")
    write(name, doc, fields + ofs + "
    @Override
    public View body(View content) {
" + body + "    }
")

u8_simple("Underline", "underlines the text ({@code UNDERLINE}).", "UNDERLINE", "on ? 1 : 0",
          "    /** Underline. */
    public static Underline of() {
        return new Underline(true);
    }

"
          "    /** Underline ({@code on} = underline). */
    public static Underline of(boolean on) {
        return new Underline(on);
    }

")
u8_simple("Strikethrough", "strikethrough the text ({@code STRIKETHROUGH}).", "STRIKETHROUGH", "on ? 1 : 0",
          "    /** Strikethrough. */
    public static Strikethrough of() {
        return new Strikethrough(true);
    }

"
          "    /** Strikethrough ({@code on} = strikethrough). */
    public static Strikethrough of(boolean on) {
        return new Strikethrough(on);
    }

")
u8_simple("AllowsHitTesting", "whether the view participates in hit testing.", "ALLOWS_HIT_TESTING", "on ? 1 : 0",
          "    /** Hit-testing on ({@code on} = participates). */
    public static AllowsHitTesting of(boolean on) {
        return new AllowsHitTesting(on);
    }

")

# Disabled -> ENABLED inverse
write("Disabled", "disables/enables the view ({@code ENABLED}: 1 = interactive).",
    f"    private final boolean disabled;

"
    f"    private Disabled(boolean disabled) {{
