export interface Opcode {
  readonly category: number;
  readonly command: number;
  readonly flags: number;
  readonly a: number;
  readonly b: number;
  readonly c: number;
}

export interface Batch {
  readonly version: number;
  readonly flags: number;
  readonly frameCount: number;
  readonly opcodes: Opcode[];
  readonly strings: Uint8Array;
}

export class PlplError extends Error {}

/** Parse a self-contained PLPL batch (bounds-checked). Throws {@link PlplError} on truncation/magic/version mismatch. */
export function parseBatch(bytes: Uint8Array): Batch {
  if (bytes.byteLength < HEADER_SIZE) {
    throw new PlplError("batch truncated");
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (view.getUint32(0, true) !== MAGIC) {
    throw new PlplError("bad batch magic");
  }
  const version = view.getUint16(4, true);
  if (version !== VERSION) {
    throw new PlplError("unsupported batch version " + version);
  }
  const flags = view.getUint16(6, true);
  const frameCount = view.getUint32(8, true);
  const opcodeCount = view.getUint32(12, true);
  const opcodesEnd = HEADER_SIZE + opcodeCount * OPCODE_SIZE;
  if (opcodesEnd + 4 > bytes.byteLength) {
    throw new PlplError("batch truncated (opcodes)");
  }
  const opcodes: Opcode[] = [];
  for (let i = 0; i < opcodeCount; i++) {
    const pos = HEADER_SIZE + i * OPCODE_SIZE;
    opcodes.push({
      category: view.getUint8(pos),
      command: view.getUint8(pos + 1),
      flags: view.getUint16(pos + 2, true),
      a: view.getUint32(pos + 4, true),
      b: view.getUint32(pos + 8, true),
      c: view.getUint32(pos + 12, true),
    });
  }
  const stringsLen = view.getUint32(opcodesEnd, true);
  const stringsStart = opcodesEnd + 4;
  if (stringsStart + stringsLen > bytes.byteLength) {
    throw new PlplError("batch truncated (strings)");
  }
  return { version, flags, frameCount, opcodes, strings: bytes.subarray(stringsStart, stringsStart + stringsLen) };
}

/** Decode a length-prefixed string (`[u32 len][bytes]`) at a relative offset into the string section. */
export function readString(strings: Uint8Array, offset: number): string {
  if (offset + 4 > strings.byteLength) {
    throw new PlplError("string offset out of range");
  }
  const view = new DataView(strings.buffer, strings.byteOffset, strings.byteLength);
  const len = view.getUint32(offset, true);
  const start = offset + 4;
  if (start + len > strings.byteLength) {
    throw new PlplError("string length out of range");
  }
  return new TextDecoder().decode(strings.subarray(start, start + len));
}
