function applyTree(op: P.Opcode, registry: NodeRegistry): void {
  switch (op.command) {
    case P.CMD_CREATE_NODE: {
      const el = createElement(op.b);
      el.setAttribute("data-pathland-id", String(op.a));
      registry.byId.set(op.a, el);
      break;
    }
    case P.CMD_DELETE_NODE: {
      const el = registry.byId.get(op.a);
      if (el) {
        el.remove();
        registry.byId.delete(op.a);
        // also remove descendants? The server sends DELETE for the subtree root; remove children recursively.
      }
      break;
    }
    case P.CMD_INSERT_CHILD: {
      const parent = registry.byId.get(op.a);
      const child = registry.byId.get(op.b);
      if (parent && child) {
        const index = Math.min(op.c, parent.children.length);
        if (index >= parent.children.length) parent.appendChild(child);
        else parent.insertBefore(child, parent.children[index]);
      }
      break;
    }
    case P.CMD_REMOVE_CHILD: {
      const parent = registry.byId.get(op.a);
      const child = registry.byId.get(op.b);
      if (parent && child) child.remove();
      break;
    }
    case P.CMD_MOVE_CHILD: {
      const parent = registry.byId.get(op.a);
      const child = registry.byId.get(op.b);
      if (parent && child) {
        child.remove();
        const index = Math.min(op.c, parent.children.length);
        if (index >= parent.children.length) parent.appendChild(child);
        else parent.insertBefore(child, parent.children[index]);
      }
      break;
    }
  }
}
```

