function applyNumericProperty(el: Element, propId: number, c: number): void {
  switch (propId) {
    case P.PROP_SELECTED: {
      const input = el.querySelector("input[type=checkbox]");
      if (input instanceof HTMLInputElement) input.checked = (c & 0xff) !== 0;
      const asButton = el.matches("[role=button],button") ? el : null;
      if (asButton) asButton.setAttribute("aria-pressed", (c & 0xff) !== 0 ? "true" : "false");
      break;
    }
    case P.PROP_VALUE: {
      const range = el.querySelector("input[type=range]");
      if (range instanceof HTMLInputElement) range.value = String(f32FromBits(c));
      const stepText = el.querySelector(".pathland-stepper span");
      if (stepText) stepText.textContent = String(Math.round(f32FromBits(c) * 100) / 100);
      break;
    }
    case P.PROP_SELECTION: {
      const select = (el instanceof HTMLSelectElement) ? el : el.querySelector("select");
      if (select instanceof HTMLSelectElement) select.value = String(c);
      break;
    }
    case P.PROP_COLOR_VALUE: {
      const color = (el instanceof HTMLInputElement && el.type === "color") ? el : el.querySelector("input[type=color]");
      if (color instanceof HTMLInputElement) color.value = argbToHex(c);
      break;
    }
    default:
      applyPropertyStyle(el, propId, 0, c);
  }
}
