```ts
import * as P from "./plpl";
import { parseBatch, PlplError } from "./plpl";
import { applyBatch, NodeRegistry } from "./apply";

export interface TransportOptions {
  url: string;
  registry: NodeRegistry;
  onBatch?: (batch: P.Batch) => void;
  onStateChange?: (state: "connecting" | "open" | "closed") => void;
}

export class Transport {
  private ws: WebSocket | null = null;
  private readonly registry: NodeRegistry;
  private readonly opts: TransportOptions;

  constructor(opts: TransportOptions) { this.opts = opts; this.registry = opts.registry; }

  connect(): void {
    const ws = new WebSocket(this.opts.url);
    ws.binaryType = "arraybuffer";
    ws.onopen = () => this.opts.onStateChange?.("open");
    ws.onmessage = (event) => this.handleMessage(event.data);
    ws.onclose = () => this.opts.onStateChange?.("closed");
    this.ws = ws;
  }

  private handleMessage(data: unknown): void {
    let bytes: Uint8Array;
    if (data instanceof ArrayBuffer) bytes = new Uint8Array(data);
    else if (data instanceof Blob) return; // server sends binary
    else bytes = new Uint8Array(0);
    try {
      const batch = parseBatch(bytes);
      if (batch.version !== P.VERSION) { location.reload(); return; }
      applyBatch(batch, this.registry);
      this.opts.onBatch?.(batch);
    } catch (err) {
      if (err instanceof PlplError) console.error("[pathland] bad batch:", err.message);
      else throw err;
    }
  }

  send(bytes: Uint8Array): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) this.ws.send(bytes);
  }
  get open(): boolean { return this.ws != null && this.ws.readyState === WebSocket.OPEN; }
}
```

