import * as P from "./plpl";

const FLAG_GUEST_TO_HOST = 0x0000;

function writeEvent(command: number, target: number, b = 0, c = 0): Uint8Array {
  const out = new Uint8Array(P.HEADER_SIZE + P.OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, P.MAGIC, true);
  view.setUint16(4, P.VERSION, true);
  view.setUint16(6, FLAG_GUEST_TO_HOST, true);
  view.setUint32(8, 0, true); // frameCount
  view.setUint32(12, 1, true); // opcodeCount
  const pos = P.HEADER_SIZE;
  view.setUint8(pos, P.CAT_EVENT);
  view.setUint8(pos + 1, command);
  view.setUint32(pos + 4, target, true);
  view.setUint32(pos + 8, b, true);
  view.setUint32(pos + 12, c, true);
  return out;
}
