```ts
export function encodeTextChanged(target: number, text: string): Uint8Array {
  const textBytes = new TextEncoder().encode(text);
  const out = new Uint8Array(P.HEADER_SIZE + P.OPCODE_SIZE + 4 + 4 + textBytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, P.MAGIC, true);
  view.setUint16(4, P.VERSION, true);
  view.setUint16(6, FLAG_GUEST_TO_HOST, true);
  view.setUint32(8, 0, true);
  view.setUint32(12, 1, true);
  const pos = P.HEADER_SIZE;
  view.setUint8(pos, P.CAT_EVENT);
  view.setUint8(pos + 1, P.CMD_TEXT_CHANGED);
  view.setUint32(pos + 4, target, true);
  view.setUint32(pos + 8, 0, true); // b = relative string offset
  view.setUint32(pos + 12, 0, true);
  // string section
  view.setUint32(P.HEADER_SIZE + P.OPCODE_SIZE, 4 + textBytes.length, true); // stringsLen
  view.setUint32(P.HEADER_SIZE + P.OPCODE_SIZE + 4, textBytes.length, true); // entry length
  out.set(textBytes, P.HEADER_SIZE + P.OPCODE_SIZE + 8);
  return out;
}
```

Wait — original offsets: out is 16+16+4+4+len. Absolute 32 = stringsLen; 36 = entry len; 40 = bytes. My version: HEADER_SIZE+OPCODE_SIZE = 32 (stringsLen), +4 = 36 (entry len), +8 = 40 (bytes). Good.

