**src/plpl.ts** — batch codec:
```ts
import { HEADER_SIZE, MAGIC, OPCODE_SIZE, VERSION, FLAG_HOST_TO_GUEST } from "./constants";

export interface Opcode {
  category: number;
  command: number;
  flags: number;
  a: number;
  b: number;
  c: number;
}

export interface Batch {
  version: number;
  flags: number;
  frameCount: number;
  opcodes: Opcode[];
  strings: Uint8Array;
}

export class ProtocolError extends Error {}

function dv(bytes: Uint8Array): DataView {
  return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
}

/** Parse a self-contained PLPL batch. Throws ProtocolError on truncation or bad magic/version. */
export function parseBatch(bytes: Uint8Array): Batch {
  if (bytes.length < HEADER_SIZE) throw new ProtocolError("batch truncated");
  const view = dv(bytes);
  if (view.getUint32(0, true) !== MAGIC) throw new ProtocolError("bad magic");
  const version = view.getUint16(4, true);
  if (version !== VERSION) throw new ProtocolError(`unsupported version ${version}`);
  const flags = view.getUint16(6, true);
  const frameCount = view.getUint32(8, true);
  const opcodeCount = view.getUint32(12, true);
  const opcodesEnd = HEADER_SIZE + opcodeCount * OPCODE_SIZE;
  if (opcodesEnd + 4 > bytes.length) throw new ProtocolError("truncated opcodes");
  const opcodes: Opcode[] = [];
  for (let i = 0; i < opcodeCount; i++) {
    const pos = HEADER_SIZE + i * OPCODE_SIZE;
    opcodes.push({
      category: view.getUint8(pos),
      command: view.getUint8(pos + 1),
      flags: view.getUint16(pos + 2, true),
      a: view.getUint32(pos + 4, true),
      b: view.getUint32(pos + 8, true),
      c: view.getUint32(pos + 12, true),
    });
  }
  const stringsLen = view.getUint32(opcodesEnd, true);
  const stringsStart = opcodesEnd + 4;
  if (stringsStart + stringsLen > bytes.length) throw new ProtocolError("truncated strings");
  return { version, flags, frameCount, opcodes, strings: bytes.subarray(stringsStart, stringsStart + stringsLen) };
}

/** Read a length-prefixed string at a relative offset into the batch's string section. Bounds-checked. */
export function readString(strings: Uint8Array, offset: number): string {
  if (offset + 4 > strings.length) throw new ProtocolError("string offset out of bounds");
  const view = dv(strings);
  const len = view.getUint32(offset, true);
  const start = offset + 4;
  if (start + len > strings.length) throw new ProtocolError("string length out of bounds");
  return new TextDecoder().decode(strings.subarray(start, start + len));
}
```

