```ts
function applyTree(op: Opcode, r: DomRenderer): void {
  switch (op.command) {
    case CMD_CREATE_NODE: {
      const el = createElement(op.b);
      if (el.nodeType === Node.ELEMENT_NODE) {
        (el as HTMLElement).setAttribute("data-pathland-id", String(op.a));
      }
      r.byId.set(op.a, el);
      break;
    }
    case CMD_DELETE_NODE: {
      const el = r.byId.get(op.a);
      if (el && el.parentNode) el.remove();
      r.byId.delete(op.a);
      break;
    }
    case CMD_INSERT_CHILD: {
      const parent = r.byId.get(op.a);
      const child = r.byId.get(op.b);
      if (parent && child) {
        const container = childrenContainer(parent);
        if (container) insertAt(container, child, op.c);
      }
      break;
    }
    case CMD_REMOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (child && child.parentNode) child.remove();
      break;
    }
    case CMD_MOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (!child) break;
      if (child.parentNode) child.remove();
      const parent = r.byId.get(op.a);
      if (parent) {
        const container = childrenContainer(parent);
        if (container) insertAt(container, child, op.c);
      }
      break;
    }
    default: break;
  }
}

function insertAt(container: Node, child: Node, index: number): void {
  const elementChildren = Array.from(container.childNodes).filter((n) => n.nodeType === Node.ELEMENT_NODE || n.nodeType === Node.COMMENT_NODE);
  const target = elementChildren[index];
  if (target) container.insertBefore(child, target);
  else container.appendChild(child);
}
```

