  stop(): void {
    this.closed = true;
    if (this.ws) {
      this.ws.onclose = null;
      this.ws.close();
      this.ws = null;
    }
  }

  get open(): boolean {
    return this.ws !== null && this.ws.readyState === WebSocket.OPEN;
  }

  send(bytes: Uint8Array): void {
    if (this.open) this.ws!.send(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength));
  }

  private connect(): void {
    const ws = this.options.createSocket ? this.options.createSocket(this.options.url) : new WebSocket(this.options.url);
    this.ws = ws;
    ws.binaryType = "arraybuffer";
    ws.onopen = () => { this.attempt = 0; this.options.onStatus?.("open"); };
    ws.onmessage = (event) => this.handleMessage(event.data);
    ws.onerror = () => { /* onclose follows */ };
    ws.onclose = () => {
      this.ws = null;
      if (this.closed) return;
      this.options.onStatus?.("reconnecting");
      this.scheduleReconnect();
    };
  }

  private scheduleReconnect(): void {
    const base = RECONNECT_DELAY_MS * 2 ** this.attempt;
    const delay = Math.min(base, RECONNECT_MAX_DELAY_MS) * (1 + (Math.random() - 0.5) * 2 * RECONNECT_JITTER);
    this.attempt++;
    setTimeout(() => this.connect(), delay);
  }

  private handleMessage(data: unknown): void {
    let bytes: Uint8Array;
    if (data instanceof ArrayBuffer) bytes = new Uint8Array(data);
    else if (data instanceof Blob) { void data.arrayBuffer().then((ab) => this.handleMessage(ab)); return; }
    else bytes = new Uint8Array(0);
    let batch: Batch;
    try {
      batch = parseBatch(bytes);
    } catch (err) {
      if (err instanceof ProtocolError) { console.error("[pathland] rejected batch:", err.message); return; }
      throw err;
    }
    if (batch.version !== VERSION) {
      console.warn(`[pathland] protocol version ${batch.version} != ${VERSION}; reloading`);
      location.reload();
      return;
    }
    applyBatch(batch, this.options.renderer);
    this.options.onBatch?.(batch);
  }
}
