// The DOM renderer's native element mapping: create the DOM shell for a node of
// the given component. Used when TREE deltas create nodes at runtime (the SSR
// path renders the shell server-side with Tailwind classes).

import {
  COMPONENT_BUTTON,
  COMPONENT_COLOR,
  COMPONENT_COLOR_PICKER,
  COMPONENT_COMMENT,
  COMPONENT_DATE_PICKER,
  COMPONENT_DIVIDER,
  COMPONENT_GAUGE,
  COMPONENT_GRID,
  COMPONENT_HSTACK,
  COMPONENT_IMAGE,
  COMPONENT_LAZY_HGRID,
  COMPONENT_LAZY_HSTACK,
  COMPONENT_LAZY_VGRID,
  COMPONENT_LAZY_VSTACK,
  COMPONENT_MENU,
  COMPONENT_PICKER,
  COMPONENT_PROGRESS_VIEW,
  COMPONENT_SCROLLVIEW,
  COMPONENT_SHAPE,
  COMPONENT_SLIDER,
  COMPONENT_SPACER,
  COMPONENT_STEPPER,
  COMPONENT_TEXT,
  COMPONENT_TEXT_EDITOR,
  COMPONENT_TEXT_FIELD,
  COMPONENT_TOGGLE,
  COMPONENT_VSTACK,
  COMPONENT_ZSTACK,
} from "./constants";

/** Create the DOM shell for a node of {@code component}. Returns a Node (elements or an inert comment). */
export function createElement(component: number): Node {
  switch (component) {
    case COMPONENT_VSTACK:
    case COMPONENT_LAZY_VSTACK:
      return flexBox("column");
    case COMPONENT_HSTACK:
    case COMPONENT_LAZY_HSTACK:
      return flexBox("row");
    case COMPONENT_ZSTACK: {
      const el = document.createElement("div");
      el.style.position = "relative";
      return el;
    }
    case COMPONENT_GRID:
    case COMPONENT_LAZY_VGRID:
    case COMPONENT_LAZY_HGRID: {
      const el = document.createElement("div");
      el.style.display = "grid";
      return el;
    }
    case COMPONENT_SCROLLVIEW: {
      const el = document.createElement("div");
      el.style.overflow = "auto";
      return el;
    }
    case COMPONENT_TEXT:
      return document.createElement("span");
    case COMPONENT_BUTTON:
      return document.createElement("button");
    case COMPONENT_IMAGE: {
      const el = document.createElement("img");
      el.alt = "";
      return el;
    }
    case COMPONENT_COLOR:
    case COMPONENT_SHAPE:
    case COMPONENT_GAUGE:
      return document.createElement("div");
    case COMPONENT_DIVIDER:
      return document.createElement("hr");
    case COMPONENT_SPACER: {
      const el = document.createElement("div");
      el.style.flex = "1";
      return el;
    }
    case COMPONENT_PROGRESS_VIEW: {
      const el = document.createElement("progress");
      el.max = 1;
      return el;
    }
    case COMPONENT_TEXT_EDITOR:
      return document.createElement("textarea");
    case COMPONENT_TEXT_FIELD:
      return textFieldShell();
    case COMPONENT_TOGGLE:
      return toggleShell();
    case COMPONENT_SLIDER:
      return sliderShell();
    case COMPONENT_STEPPER:
      return stepperShell();
    case COMPONENT_PICKER:
      return document.createElement("select");
    case COMPONENT_MENU:
      return menuShell();
    case COMPONENT_COLOR_PICKER: {
      const el = document.createElement("input");
      el.type = "color";
      return el;
    }
    case COMPONENT_DATE_PICKER: {
      const el = document.createElement("input");
      el.type = "date";
      return el;
    }
    case COMPONENT_COMMENT:
      return document.createComment("");
    default:
      return document.createElement("div");
  }
}

function flexBox(direction: "column" | "row"): HTMLElement {
  const el = document.createElement("div");
  el.style.display = "flex";
  el.style.flexDirection = direction;
  return el;
}

/** `<label class="pathland-textfield"><span class="pathland-label"></span><input type="text"></label>` */
function textFieldShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-textfield";
  const span = document.createElement("span");
  span.className = "pathland-label";
  const input = document.createElement("input");
  input.type = "text";
  label.append(span, input);
  return label;
}

/** `<label class="pathland-toggle"><input type="checkbox"><span class="pathland-text"></span></label>` */
function toggleShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-toggle";
  const input = document.createElement("input");
  input.type = "checkbox";
  const span = document.createElement("span");
  span.className = "pathland-text";
  label.append(input, span);
  return label;
}

/** `<label class="pathland-slider"><input type="range" step="any"><span class="pathland-text"></span></label>` */
function sliderShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-slider";
  const input = document.createElement("input");
  input.type = "range";
  input.step = "any";
  const span = document.createElement("span");
  span.className = "pathland-text";
  label.append(input, span);
  return label;
}

/** `<div class="pathland-stepper"><button data-step="-1">−</button><span></span><button data-step="1">+</button><span class="pathland-stepper-range" hidden></span></div>` */
function stepperShell(): HTMLElement {
  const el = document.createElement("div");
  el.className = "pathland-stepper";
  const minus = document.createElement("button");
  minus.type = "button";
  minus.dataset.step = "-1";
  minus.textContent = "−";
  const value = document.createElement("span");
  const plus = document.createElement("button");
  plus.type = "button";
  plus.dataset.step = "1";
  plus.textContent = "+";
  const range = document.createElement("span");
  range.className = "pathland-stepper-range";
  range.hidden = true;
  el.append(minus, value, plus, range);
  return el;
}

/** `<div class="pathland-menu"><div class="pathland-menu-trigger"></div><div class="pathland-menu-items"></div></div>` */
function menuShell(): HTMLElement {
  const el = document.createElement("div");
  el.className = "pathland-menu";
  const trigger = document.createElement("div");
  trigger.className = "pathland-menu-trigger";
  const items = document.createElement("div");
  items.className = "pathland-menu-items";
  el.append(trigger, items);
  return el;
}

/**
 * The container a node's TREE children are inserted into. Most nodes append
 * children directly; composite shells route them into their label/trigger span.
 */
export function childrenContainer(node: Node): Node | null {
  if (node instanceof HTMLElement) {
    if (node.classList.contains("pathland-menu")) {
      return node.querySelector(".pathland-menu-items");
    }
    if (node.classList.contains("pathland-toggle") || node.classList.contains("pathland-slider")) {
      return node.querySelector(".pathland-text");
    }
    if (node.classList.contains("pathland-textfield")) {
      return node.querySelector(".pathland-label");
    }
  }
  return node;
}

// Option A styling: the DOM renderer owns a bounded property → style/class map.
// The protocol stays renderer-agnostic; web-specific Tailwind class resolution
// is the HTML renderer's job (SSR). At runtime, STYLE deltas are applied as
// inline style (which overrides the SSR Tailwind class for the current value),
// literal colors via inline style, and semantic design tokens as CSS variables.

import {
  ALIGN_CENTER,
  ALIGN_FILL,
  ALIGN_LEADING,
  ALIGN_TRAILING,
  PROP_ALIGNMENT,
  PROP_BACKGROUND_COLOR,
  PROP_BORDER_COLOR,
  PROP_BORDER_RADIUS,
  PROP_BORDER_WIDTH,
  PROP_COLOR,
  PROP_CONTENT_MARGINS,
  PROP_ENABLED,
  PROP_HEIGHT,
  PROP_OPACITY,
  PROP_PADDING,
  PROP_PADDING_BOTTOM,
  PROP_PADDING_LEFT,
  PROP_PADDING_RIGHT,
  PROP_PADDING_TOP,
  PROP_SPACING,
  PROP_VISIBLE,
  PROP_WIDTH,
  WIDTH_FILL,
  WIDTH_HUG,
} from "./constants";
import { argbToRgba, f32FromBits, fmtFloat } from "./format";

/** Apply a numeric style property to an element via inline style. */
export function applyStyleProperty(el: HTMLElement, property: number, bits: number): void {
  switch (property) {
    case PROP_SPACING:
      el.style.gap = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_ALIGNMENT:
      el.style.alignItems = alignmentCss(bits);
      break;
    case PROP_CONTENT_MARGINS:
      el.style.padding = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_PADDING:
      el.style.padding = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_PADDING_TOP:
      el.style.paddingTop = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_PADDING_RIGHT:
      el.style.paddingRight = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_PADDING_BOTTOM:
      el.style.paddingBottom = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_PADDING_LEFT:
      el.style.paddingLeft = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_COLOR:
      el.style.color = argbToRgba(bits);
      break;
    case PROP_BACKGROUND_COLOR:
      el.style.backgroundColor = argbToRgba(bits);
      break;
    case PROP_BORDER_COLOR:
      el.style.borderColor = argbToRgba(bits);
      break;
    case PROP_BORDER_WIDTH:
      el.style.borderWidth = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_BORDER_RADIUS:
      el.style.borderRadius = fmtFloat(f32FromBits(bits)) + "px";
      break;
    case PROP_OPACITY:
      el.style.opacity = fmtFloat(f32FromBits(bits));
      break;
    case PROP_VISIBLE:
      el.style.display = bits === 0 ? "none" : "";
      break;
    case PROP_WIDTH:
      el.style.width = sizeCss(bits);
      break;
    case PROP_HEIGHT:
      el.style.height = sizeCss(bits);
      break;
    default:
      break;
  }
}

/** Apply a state-class/ARIA toggle for a numeric {@link PROP_ENABLED} delta. */
export function applyEnabled(el: HTMLElement, bits: number): void {
  const disabled = bits === 0;
  if (
    el instanceof HTMLInputElement ||
    el instanceof HTMLButtonElement ||
    el instanceof HTMLSelectElement ||
    el instanceof HTMLTextAreaElement
  ) {
    el.disabled = disabled;
  } else if (disabled) {
    el.setAttribute("aria-disabled", "true");
  } else {
    el.removeAttribute("aria-disabled");
  }
}

/** Map the protocol {@link Alignment} enum to the cross-axis CSS value. */
export function alignmentCss(bits: number): string {
  switch (bits) {
    case ALIGN_LEADING:
      return "flex-start";
    case ALIGN_TRAILING:
      return "flex-end";
    case ALIGN_FILL:
      return "stretch";
    case ALIGN_CENTER:
    default:
      return "center";
  }
}

/** Map a {@link WIDTH}/{@link HEIGHT} value (FILL/HUG/fixed px) to CSS. */
export function sizeCss(bits: number): string {
  const value = f32FromBits(bits);
  if (value === WIDTH_FILL) {
    return "100%";
  }
  if (value === WIDTH_HUG) {
    return "fit-content";
  }
  return fmtFloat(value) + "px";
}

// Delta application: decode each opcode and apply it to the DOM via the
// retained `id → Node` registry. STYLE deltas mutate the hydrated element in
// place; TREE deltas build the element shell and insert/remove/move it.

import {
  CAT_STYLE,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_DELETE_NODE,
  CMD_INSERT_CHILD,
  CMD_MOVE_CHILD,
  CMD_REMOVE_CHILD,
  CMD_SET_DATE,
  CMD_SET_PROPERTY,
  CMD_SET_TEXT,
  PROP_COLOR_VALUE,
  PROP_ENABLED,
  PROP_LABEL,
  PROP_PROMPT,
  PROP_SELECTED,
  PROP_SELECTION,
  PROP_VALUE,
  VAL_STRING,
} from "./constants";
import type { Batch, Opcode } from "./plpl";
import { readString } from "./plpl";
import { childrenContainer, createElement } from "./elements";
import { applyEnabled, applyStyleProperty } from "./classes";
import { argbToHex, daysToIso, f32FromBits } from "./format";

/** The retained `node id → DOM Node` registry the renderer works against. */
export interface DomRenderer {
  byId: Map<number, Node>;
}

/** Apply every opcode in a batch to the DOM (TREE structure + STYLE deltas). */
export function applyBatch(batch: Batch, renderer: DomRenderer): void {
  for (const op of batch.opcodes) {
    switch (op.category) {
      case CAT_TREE:
        applyTree(op, renderer);
        break;
      case CAT_STYLE:
        applyStyle(op, batch.strings, renderer);
        break;
      default:
        break;
    }
  }
}

function applyTree(op: Opcode, r: DomRenderer): void {
  switch (op.command) {
    case CMD_CREATE_NODE: {
      const el = createElement(op.b);
      if (el.nodeType === Node.ELEMENT_NODE) {
        (el as HTMLElement).setAttribute("data-pathland-id", String(op.a));
      }
      r.byId.set(op.a, el);
      break;
    }
    case CMD_DELETE_NODE: {
      const el = r.byId.get(op.a);
      if (el && el.parentNode) {
        el.remove();
      }
      r.byId.delete(op.a);
      break;
    }
    case CMD_INSERT_CHILD: {
      const parent = r.byId.get(op.a);
      const child = r.byId.get(op.b);
      if (parent && child) {
        const container = childrenContainer(parent);
        if (container) {
          insertAt(container, child, op.c);
        }
      }
      break;
    }
    case CMD_REMOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (child && child.parentNode) {
        child.remove();
      }
      break;
    }
    case CMD_MOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (!child) {
        break;
      }
      if (child.parentNode) {
        child.remove();
      }
      const parent = r.byId.get(op.a);
      if (parent) {
        const container = childrenContainer(parent);
        if (container) {
          insertAt(container, child, op.c);
        }
      }
      break;
    }
    default:
      break;
  }
}

function insertAt(container: Node, child: Node, index: number): void {
  const visible = Array.from(container.childNodes).filter(
    (n) => n.nodeType === Node.ELEMENT_NODE || n.nodeType === Node.COMMENT_NODE,
  );
  const target = visible[index];
  if (target) {
    container.insertBefore(child, target);
  } else {
    container.appendChild(child);
  }
}

function applyStyle(op: Opcode, strings: Uint8Array, r: DomRenderer): void {
  const node = r.byId.get(op.a);
  if (!node || node.nodeType !== Node.ELEMENT_NODE) {
    return;
  }
  const el = node as HTMLElement;
  switch (op.command) {
    case CMD_SET_TEXT:
      setNodeText(el, readString(strings, op.b));
      break;
    case CMD_SET_DATE: {
      const input = el.matches("input[type=date]") ? el : el.querySelector("input[type=date]");
      if (input instanceof HTMLInputElement) {
        input.value = daysToIso(op.b);
      }
      break;
    }
    case CMD_SET_PROPERTY: {
      const propId = op.b & 0xffff;
      const valueType = (op.b >>> 16) & 0xff;
      if (valueType === VAL_STRING) {
        applyStringProperty(el, propId, readString(strings, op.c));
      } else {
        applyNumericProperty(el, propId, op.c);
      }
      break;
    }
    default:
      break;
  }
}

/** Set a node's text, honoring text fields/editors and label spans (SSR structure). */
export function setNodeText(el: HTMLElement, text: string): void {
  const input = el.querySelector("input[type=text]");
  if (input instanceof HTMLInputElement) {
    input.value = text;
    return;
  }
  const textarea = el.querySelector("textarea");
  if (textarea instanceof HTMLTextAreaElement) {
    textarea.value = text;
    return;
  }
  const span = el.querySelector(".pathland-text");
  if (span) {
    span.textContent = text;
    return;
  }
  el.textContent = text;
}

function applyStringProperty(el: HTMLElement, propId: number, text: string): void {
  switch (propId) {
    case PROP_LABEL: {
      const span = el.querySelector(".pathland-label");
      if (span) {
        span.textContent = text;
      }
      break;
    }
    case PROP_PROMPT: {
      const input = el.querySelector("input[type=text]");
      if (input instanceof HTMLInputElement) {
        input.placeholder = text;
      }
      break;
    }
    default:
      break;
  }
}

function applyNumericProperty(el: HTMLElement, propId: number, bits: number): void {
  switch (propId) {
    case PROP_SELECTED: {
      const input = el.querySelector("input[type=checkbox]");
      if (input instanceof HTMLInputElement) {
        input.checked = (bits & 0xff) !== 0;
      }
      break;
    }
    case PROP_VALUE: {
      const range = el.querySelector("input[type=range]");
      if (range instanceof HTMLInputElement) {
        range.value = String(f32FromBits(bits));
      }
      const stepText = el.querySelector(".pathland-stepper span");
      if (stepText) {
        stepText.textContent = String(Math.round(f32FromBits(bits) * 100) / 100);
      }
      break;
    }
    case PROP_SELECTION: {
      const select = el.matches("select") ? el : el.querySelector("select");
      if (select instanceof HTMLSelectElement) {
        select.value = String(bits);
      }
      break;
    }
    case PROP_COLOR_VALUE: {
      const input = el.matches("input[type=color]") ? el : el.querySelector("input[type=color]");
      if (input instanceof HTMLInputElement) {
        input.value = argbToHex(bits);
      }
      break;
    }
    case PROP_ENABLED:
      applyEnabled(el, bits);
      break;
    default:
      applyStyleProperty(el, propId, bits);
      break;
  }
}

