// Host → guest event encoders. Each call produces a self-contained PLPL batch
// with a single EVENT opcode (guest → host direction, flags = 0x0000).

import {
  CAT_EVENT,
  CMD_DATE_CHANGED,
  CMD_POINTER_UP,
  CMD_TEXT_CHANGED,
  CMD_VALUE_CHANGED,
  HEADER_SIZE,
  MAGIC,
  OPCODE_SIZE,
  VERSION,
} from "./constants";
import { bitsFromF32 } from "./format";

function eventBatch(command: number, a: number, b: number, c: number): Uint8Array {
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true); // flags = guest -> host
  view.setUint32(8, 0, true); // frameCount
  view.setUint32(12, 1, true); // opcodeCount
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, command);
  view.setUint32(pos + 4, a, true);
  view.setUint32(pos + 8, b, true);
  view.setUint32(pos + 12, c, true);
  return out;
}

/** A button tap: POINTER_UP on the target node. */
export function encodePointerUp(target: number): Uint8Array {
  return eventBatch(CMD_POINTER_UP, target, 0, 0);
}

/** A VALUE_CHANGED EVENT with the value as f32 bits (toggle 0/1, slider, select index, stepper). */
export function encodeValueChanged(target: number, value: number): Uint8Array {
  return eventBatch(CMD_VALUE_CHANGED, target, bitsFromF32(value), 0);
}

/** A VALUE_CHANGED EVENT with a raw 32-bit payload (e.g. a packed ARGB color). */
export function encodeValueBits(target: number, bits: number): Uint8Array {
  return eventBatch(CMD_VALUE_CHANGED, target, bits >>> 0, 0);
}

/** A DATE_CHANGED EVENT (A=target, B=days, C=millis of day). */
export function encodeDateChanged(target: number, days: number, millis: number): Uint8Array {
  return eventBatch(CMD_DATE_CHANGED, target, days >>> 0, millis >>> 0);
}

/** A TEXT_CHANGED EVENT; the text rides in the batch's string section (B = relative offset). */
export function encodeTextChanged(target: number, text: string): Uint8Array {
  const bytes = new TextEncoder().encode(text);
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4 + 4 + bytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, 0, true);
  view.setUint32(12, 1, true);
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, CMD_TEXT_CHANGED);
  view.setUint32(pos + 4, target, true);
  view.setUint32(pos + 8, 0, true); // b = relative string offset (first entry)
  view.setUint32(pos + 12, 0, true);
  // string section: [stringsLen u32][entryLen u32][utf8…]
  const stringsAt = HEADER_SIZE + OPCODE_SIZE;
  view.setUint32(stringsAt, 4 + bytes.length, true);
  view.setUint32(stringsAt + 4, bytes.length, true);
  out.set(bytes, stringsAt + 8);
  return out;
}

// WebSocket transport: connects to the server's `/ws`, applies each received
// PLPL batch to the DOM renderer, negotiates the protocol version, and reports
// raw-input events back. Reconnect/backoff live here; session-resync and
// frameCount gap handling are P3 (the module seam is the `onBatch` hook).

import type { Batch } from "./plpl";
import { ProtocolError, parseBatch } from "./plpl";
import { applyBatch, type DomRenderer } from "./apply";
import { VERSION } from "./constants";

export type TransportStatus = "connecting" | "open" | "reconnecting";

export interface TransportOptions {
  /** WebSocket URL, e.g. `ws://host/ws`. */
  url: string;
  /** The retained-node registry deltas are applied to. */
  renderer: DomRenderer;
  /** Invoked after a batch is successfully applied (P3: resync/frameCount hooks). */
  onBatch?: (batch: Batch) => void;
  onStatus?: (status: TransportStatus) => void;
  /** Injectable socket factory (tests). */
  createSocket?: (url: string) => WebSocket;
}

const BASE_DELAY_MS = 500;
const MAX_DELAY_MS = 30000;
const MAX_ATTEMPTS = 30;

export class Transport {
  private ws: WebSocket | null = null;
  private attempt = 0;
  private stopped = false;
  private readonly options: TransportOptions;

  constructor(options: TransportOptions) {
    this.options = options;
  }

  /** Connect and stay connected (auto-reconnect with exponential backoff). */
  start(): void {
    this.stopped = false;
    this.connect();
  }

  /** Permanently close the socket and cancel reconnects. */
  stop(): void {
    this.stopped = true;
    if (this.ws) {
      this.ws.onclose = null;
      this.ws.close();
      this.ws = null;
    }
  }

  get open(): boolean {
    return this.ws !== null && this.ws.readyState === WebSocket.OPEN;
  }

  send(bytes: Uint8Array): void {
    if (this.open) {
      this.ws!.send(bytes);
    }
  }

  private connect(): void {
    const ws = this.options.createSocket
      ? this.options.createSocket(this.options.url)
      : new WebSocket(this.options.url);
    this.ws = ws;
    ws.binaryType = "arraybuffer";
    ws.onopen = () => {
      this.attempt = 0;
      this.options.onStatus?.("open");
    };
    ws.onmessage = (event) => this.handleMessage(event.data);
    ws.onerror = () => {
      // onclose always follows; nothing to do here.
    };
    ws.onclose = () => {
      this.ws = null;
      if (this.stopped) {
        return;
      }
      this.options.onStatus?.("reconnecting");
      this.scheduleReconnect();
    };
  }

  private scheduleReconnect(): void {
    if (this.attempt >= MAX_ATTEMPTS) {
      return;
    }
    const delay = Math.min(BASE_DELAY_MS * 2 ** this.attempt, MAX_DELAY_MS);
    this.attempt++;
    setTimeout(() => this.connect(), delay);
  }

  private handleMessage(data: unknown): void {
    let bytes: Uint8Array;
    if (data instanceof ArrayBuffer) {
      bytes = new Uint8Array(data);
    } else if (data instanceof Blob) {
      void data.arrayBuffer().then((buffer) => this.handleMessage(buffer));
      return;
    } else {
      bytes = new Uint8Array(0);
    }
    let batch: Batch;
    try {
      batch = parseBatch(bytes);
    } catch (err) {
      if (err instanceof ProtocolError) {
        console.error("[pathland] rejected batch:", err.message);
        return;
      }
      throw err;
    }
    if (batch.version !== VERSION) {
      console.warn(`[pathland] protocol version ${batch.version} != ${VERSION}; reloading`);
      location.reload();
      return;
    }
    try {
      applyBatch(batch, this.options.renderer);
    } catch (err) {
      if (err instanceof ProtocolError) {
        console.error("[pathland] rejected delta:", err.message);
        return;
      }
      throw err;
    }
    this.options.onBatch?.(batch);
  }
}

// The Pathland DOM renderer bootstrap. Hydrates the server-rendered DOM,
// connects to the WebSocket, applies PLPL deltas in place, and reports raw
// inputs back as host → guest EVENT batches. Bundle: dist/pathland-dom-renderer.js

import type { DomRenderer } from "./apply";
import { Transport } from "./transport";
import {
  encodeDateChanged,
  encodePointerUp,
  encodeTextChanged,
  encodeValueBits,
  encodeValueChanged,
} from "./events";

function boot(): void {
  const byId = new Map<number, Node>();
  for (const el of document.querySelectorAll<HTMLElement>("[data-pathland-id]")) {
    byId.set(Number(el.getAttribute("data-pathland-id")), el);
  }
  const renderer: DomRenderer = { byId };
  const transport = new Transport({
    url: `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/ws`,
    renderer,
  });
  transport.start();

  // Buttons (and stepper +/− buttons) report a tap/step as an event.
  document.addEventListener("click", (event) => {
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const button = target.closest<HTMLElement>("button[data-pathland-id]");
    if (button && transport.open) {
      transport.send(encodePointerUp(Number(button.getAttribute("data-pathland-id"))));
      return;
    }
    const stepButton = target.closest<HTMLElement>(".pathland-stepper button[data-step]");
    if (stepButton && transport.open) {
      const stepper = stepButton.closest<HTMLElement>(".pathland-stepper[data-pathland-id]");
      if (stepper) {
        const id = Number(stepper.getAttribute("data-pathland-id"));
        const valueEl = stepper.querySelector("span");
        const rangeEl = stepper.querySelector<HTMLElement>(".pathland-stepper-range");
        const current = Number(valueEl ? valueEl.textContent : 0);
        const dir = Number(stepButton.getAttribute("data-step"));
        const min = Number(rangeEl?.getAttribute("data-min"));
        const max = Number(rangeEl?.getAttribute("data-max"));
        const step = Number(rangeEl?.getAttribute("data-step"));
        const next = Math.min(max, Math.max(min, current + dir * step));
        transport.send(encodeValueChanged(id, next));
      }
    }
  });

  // Toggles report boolean state, selects the option index, pickers raw values.
  document.addEventListener("change", (event) => {
    if (!transport.open) {
      return;
    }
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const toggle = target.closest<HTMLElement>("label.pathland-toggle[data-pathland-id]");
    if (toggle) {
      const box = toggle.querySelector<HTMLInputElement>("input[type=checkbox]");
      transport.send(
        encodeValueChanged(Number(toggle.getAttribute("data-pathland-id")), box && box.checked ? 1 : 0),
      );
      return;
    }
    const select = target.closest<HTMLSelectElement>("select[data-pathland-id]");
    if (select) {
      transport.send(encodeValueChanged(Number(select.getAttribute("data-pathland-id")), Number(select.value)));
      return;
    }
    const color = target.closest<HTMLInputElement>("input[type=color][data-pathland-id]");
    if (color) {
      const rgb = parseInt(color.value.slice(1), 16);
      transport.send(encodeValueBits(Number(color.getAttribute("data-pathland-id")), 0xff000000 | rgb));
      return;
    }
    const date = target.closest<HTMLInputElement>("input[type=date][data-pathland-id]");
    if (date && date.value) {
      const [y, m, d] = date.value.split("-").map(Number);
      const days = Math.round(Date.UTC(y, m - 1, d) / 86400000);
      transport.send(encodeDateChanged(Number(date.getAttribute("data-pathland-id")), days, 0));
    }
  });

  // Sliders report live while dragging; text fields/editors report live while typing.
  document.addEventListener("input", (event) => {
    if (!transport.open) {
      return;
    }
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const slider = target.closest<HTMLInputElement>("input[type=range]");
    if (slider) {
      const label = slider.closest<HTMLElement>("label.pathland-slider[data-pathland-id]");
      if (label) {
        transport.send(encodeValueChanged(Number(label.getAttribute("data-pathland-id")), Number(slider.value)));
      }
      return;
    }
    const textarea = target.closest<HTMLTextAreaElement>("textarea[data-pathland-id]");
    if (textarea) {
      transport.send(encodeTextChanged(Number(textarea.getAttribute("data-pathland-id")), textarea.value));
      return;
    }
    const input = target.closest<HTMLInputElement>("input[type=text]");
    if (!input) {
      return;
    }
    const label = input.closest<HTMLElement>("label.pathland-textfield[data-pathland-id]");
    if (label) {
      transport.send(encodeTextChanged(Number(label.getAttribute("data-pathland-id")), input.value));
    }
  });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot);
} else {
  boot();
}

