import { describe, expect, it } from "vitest";
import { ProtocolError, parseBatch, readString } from "../src/plpl";
import { HEADER_SIZE, MAGIC, OPCODE_SIZE, VERSION } from "../src/constants";

/** Build a self-contained PLPL batch (header + opcodes + string section). */
export function buildBatch(opcodes: number[][], strings?: Uint8Array): Uint8Array {
  const str = strings ?? new Uint8Array(0);
  const out = new Uint8Array(HEADER_SIZE + opcodes.length * OPCODE_SIZE + 4 + str.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, 3, true); // frameCount
  view.setUint32(12, opcodes.length, true);
  opcodes.forEach((op, i) => {
    const pos = HEADER_SIZE + i * OPCODE_SIZE;
    view.setUint8(pos, op[0]!);
    view.setUint8(pos + 1, op[1]!);
    view.setUint16(pos + 2, op[2] ?? 0, true);
    view.setUint32(pos + 4, op[3] ?? 0, true);
    view.setUint32(pos + 8, op[4] ?? 0, true);
    view.setUint32(pos + 12, op[5] ?? 0, true);
  });
  view.setUint32(HEADER_SIZE + opcodes.length * OPCODE_SIZE, str.length, true);
  out.set(str, HEADER_SIZE + opcodes.length * OPCODE_SIZE + 4);
  return out;
}

/** A `[u32 len][utf8]` string entry for the string section. */
export function stringEntry(text: string): Uint8Array {
  const bytes = new TextEncoder().encode(text);
  const out = new Uint8Array(4 + bytes.length);
  new DataView(out.buffer).setUint32(0, bytes.length, true);
  out.set(bytes, 4);
  return out;
}

describe("parseBatch", () => {
  it("parses a batch with a string section", () => {
    const batch = parseBatch(buildBatch([[2, 3, 0, 7, 0, 0]], stringEntry("hi")));
    expect(batch.version).toBe(VERSION);
    expect(batch.flags).toBe(0);
    expect(batch.frameCount).toBe(3);
    expect(batch.opcodes).toHaveLength(1);
    expect(batch.opcodes[0]).toEqual({ category: 2, command: 3, flags: 0, a: 7, b: 0, c: 0 });
    expect(readString(batch.strings, 0)).toBe("hi");
  });

  it("rejects a truncated batch", () => {
    expect(() => parseBatch(new Uint8Array(8))).toThrow(ProtocolError);
  });

  it("rejects a bad magic", () => {
    const bytes = buildBatch([]);
    bytes[0] = 0x00;
    expect(() => parseBatch(bytes)).toThrow(ProtocolError);
  });

  it("rejects an unsupported version", () => {
    const bytes = buildBatch([]);
    new DataView(bytes.buffer).setUint16(4, 2, true);
    expect(() => parseBatch(bytes)).toThrow(/unsupported version 2/);
  });

  it("rejects truncated opcodes", () => {
    const bytes = buildBatch([]);
    new DataView(bytes.buffer).setUint32(12, 1000, true);
    expect(() => parseBatch(bytes)).toThrow(ProtocolError);
  });

  it("rejects a truncated string section", () => {
    const batch = parseBatch(buildBatch([[2, 3, 0, 7, 0, 0]], new Uint8Array([10, 0, 0, 0])));
    expect(() => readString(batch.strings, 0)).toThrow(ProtocolError);
  });

  it("rejects a string offset out of bounds", () => {
    const batch = parseBatch(buildBatch([]));
    expect(() => readString(batch.strings, 1)).toThrow(ProtocolError);
  });
});

import { describe, expect, it } from "vitest";
import { applyBatch, setNodeText, type DomRenderer } from "../src/apply";
import { parseBatch } from "../src/plpl";
import {
  CAT_STYLE,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_INSERT_CHILD,
  CMD_MOVE_CHILD,
  CMD_SET_TEXT,
  COMPONENT_BUTTON,
  COMPONENT_SLIDER,
  COMPONENT_TEXT,
  COMPONENT_TOGGLE,
  COMPONENT_VSTACK,
  PROP_SELECTED,
  PROP_VALUE,
} from "../src/constants";
import { buildBatch, stringEntry } from "./plpl.test";

function renderer(): DomRenderer {
  return { byId: new Map<number, Node>() };
}

describe("applyBatch · STYLE", () => {
  it("applies SET_TEXT to a hydrated span", () => {
    const span = document.createElement("span");
    span.setAttribute("data-pathland-id", "1");
    const r = renderer();
    r.byId.set(1, span);
    const batch = parseBatch(buildBatch([[CAT_STYLE, CMD_SET_TEXT, 0, 1, 0, 0]], stringEntry("hi!")));
    applyBatch(batch, r);
    expect(span.textContent).toBe("hi!");
  });

  it("applies SET_TEXT to a text field's input", () => {
    const tf = document.createElement("label");
    tf.className = "pathland-textfield";
    const input = document.createElement("input");
    input.type = "text";
    tf.appendChild(input);
    const r = renderer();
    r.byId.set(5, tf);
    applyBatch(parseBatch(buildBatch([[CAT_STYLE, CMD_SET_TEXT, 0, 5, 0, 0]], stringEntry("ab"))), r);
    expect(input.value).toBe("ab");
  });

  it("applies SELECTED to a toggle checkbox", () => {
    const toggle = document.createElement("label");
    toggle.className = "pathland-toggle";
    const box = document.createElement("input");
    box.type = "checkbox";
    toggle.appendChild(box);
    const r = renderer();
    r.byId.set(4, toggle);
    applyBatch(parseBatch(buildBatch([[CAT_STYLE, 1, 0, 4, (0 << 16) | PROP_SELECTED, 1]])), r);
    expect(box.checked).toBe(true);
  });

  it("applies VALUE to a slider", () => {
    const slider = document.createElement("label");
    slider.className = "pathland-slider";
    const range = document.createElement("input");
    range.type = "range";
    slider.appendChild(range);
    const r = renderer();
    r.byId.set(6, slider);
    const bits = new Uint32Array(new Float32Array([0.75]).buffer)[0]!;
    applyBatch(parseBatch(buildBatch([[CAT_STYLE, 1, 0, 6, (0 << 16) | PROP_VALUE, bits]])), r);
    expect(range.value).toBe("0.75");
  });
});

describe("applyBatch · TREE", () => {
  it("builds a stack: create nodes, insert, then set text", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch(
        [
          [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_VSTACK],
          [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
          [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
          [CAT_STYLE, CMD_SET_TEXT, 0, 2, 0],
        ],
        stringEntry("x"),
      ),
    );
    applyBatch(batch, r);
    const stack = r.byId.get(1) as HTMLElement;
    expect(stack).toBeInstanceOf(HTMLDivElement);
    expect(stack.style.display).toBe("flex");
    expect(stack.style.flexDirection).toBe("column");
    expect(r.byId.get(2)?.textContent).toBe("x");
    expect(stack.children).toHaveLength(1);
    expect(stack.firstElementChild?.getAttribute("data-pathland-id")).toBe("2");
  });

  it("removes a node from the DOM", () => {
    const root = document.createElement("div");
    const button = document.createElement("button");
    button.setAttribute("data-pathland-id", "9");
    root.appendChild(button);
    const r = renderer();
    r.byId.set(9, button);
    applyBatch(parseBatch(buildBatch([[CAT_TREE, 2, 0, 9, 0, 0]])), r);
    expect(root.childNodes).toHaveLength(0);
    expect(r.byId.has(9)).toBe(false);
  });

  it("inserts children at the requested index", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_VSTACK],
        [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_BUTTON],
        [CAT_TREE, CMD_CREATE_NODE, 0, 3, COMPONENT_TEXT],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 3],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2, 0],
      ]),
    );
    applyBatch(batch, r);
    const stack = r.byId.get(1) as HTMLElement;
    expect(stack.children[0]?.getAttribute("data-pathland-id")).toBe("2");
    expect(stack.children[1]?.getAttribute("data-pathland-id")).toBe("3");
  });

  it("moves a child to a new index", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_VSTACK],
        [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
        [CAT_TREE, CMD_CREATE_NODE, 0, 3, COMPONENT_TEXT],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 3],
        [CAT_TREE, CMD_MOVE_CHILD, 0, 1, 2, 1],
      ]),
    );
    applyBatch(batch, r);
    const stack = r.byId.get(1) as HTMLElement;
    expect(stack.children[0]?.getAttribute("data-pathland-id")).toBe("3");
    expect(stack.children[1]?.getAttribute("data-pathland-id")).toBe("2");
  });
});

describe("setNodeText", () => {
  it("writes through to the composite's label span", () => {
    const slider = document.createElement("label");
    slider.className = "pathland-slider";
    const input = document.createElement("input");
    input.type = "range";
    const span = document.createElement("span");
    span.className = "pathland-text";
    slider.append(input, span);
    setNodeText(slider, "50%");
    expect(span.textContent).toBe("50%");
  });
});

import { describe, expect, it } from "vitest";
import {
  encodeDateChanged,
  encodePointerUp,
  encodeTextChanged,
  encodeValueBits,
  encodeValueChanged,
} from "../src/events";
import {
  CAT_EVENT,
  CMD_DATE_CHANGED,
  CMD_POINTER_UP,
  CMD_TEXT_CHANGED,
  CMD_VALUE_CHANGED,
  HEADER_SIZE,
  MAGIC,
  VERSION,
} from "../src/constants";
import { parseBatch, readString } from "../src/plpl";

describe("event encoders", () => {
  it("encodePointerUp: header + single EVENT opcode, guest->host", () => {
    const bytes = encodePointerUp(42);
    expect(bytes.length).toBe(HEADER_SIZE + 16 + 4);
    const view = new DataView(bytes.buffer);
    expect(view.getUint32(0, true)).toBe(MAGIC);
    expect(view.getUint16(4, true)).toBe(VERSION);
    expect(view.getUint16(6, true)).toBe(0); // guest -> host
    expect(view.getUint32(8, true)).toBe(0); // frameCount
    expect(view.getUint32(12, true)).toBe(1); // opcodeCount
    expect(view.getUint8(HEADER_SIZE)).toBe(CAT_EVENT);
    expect(view.getUint8(HEADER_SIZE + 1)).toBe(CMD_POINTER_UP);
    expect(view.getUint32(HEADER_SIZE + 4, true)).toBe(42);
  });

  it("encodeValueChanged packs the f32 value into B", () => {
    const view = new DataView(encodeValueChanged(7, 0.5).buffer);
    expect(view.getUint8(HEADER_SIZE + 1)).toBe(CMD_VALUE_CHANGED);
    const bits = view.getUint32(HEADER_SIZE + 8, true);
    expect(new Float32Array(new Uint32Array([bits]).buffer)[0]).toBe(0.5);
  });

  it("encodeValueBits passes raw bits through B", () => {
    const view = new DataView(encodeValueBits(3, 0xff000000 | 0xabcdef).buffer);
    expect(view.getUint32(HEADER_SIZE + 8, true)).toBe(0xffabcdef);
  });

  it("encodeDateChanged packs days + millis into B/C", () => {
    const view = new DataView(encodeDateChanged(9, 20000, 3600000).buffer);
    expect(view.getUint8(HEADER_SIZE + 1)).toBe(CMD_DATE_CHANGED);
    expect(view.getUint32(HEADER_SIZE + 8, true)).toBe(20000);
    expect(view.getUint32(HEADER_SIZE + 12, true)).toBe(3600000);
  });

  it("encodeTextChanged rides text in the string section (round-trips)", () => {
    const batch = parseBatch(encodeTextChanged(11, "hello"));
    expect(batch.opcodes[0]?.category).toBe(CAT_EVENT);
    expect(batch.opcodes[0]?.command).toBe(CMD_TEXT_CHANGED);
    expect(batch.opcodes[0]?.a).toBe(11);
    expect(readString(batch.strings, batch.opcodes[0]!.b)).toBe("hello");
  });
});

import { describe, expect, it } from "vitest";
import { alignmentCss, applyEnabled, applyStyleProperty, sizeCss } from "../src/classes";
import {
  ALIGN_CENTER,
  ALIGN_LEADING,
  ALIGN_TRAILING,
  PROP_BACKGROUND_COLOR,
  PROP_OPACITY,
  PROP_SPACING,
  PROP_WIDTH,
} from "../src/constants";
import { bitsFromF32 } from "../src/format";

describe("Option A style appliers", () => {
  it("spacing -> gap", () => {
    const el = document.createElement("div");
    applyStyleProperty(el, PROP_SPACING, bitsFromF32(13));
    expect(el.style.gap).toBe("13px");
  });

  it("opacity -> inline opacity", () => {
    const el = document.createElement("div");
    applyStyleProperty(el, PROP_OPACITY, bitsFromF32(0.5));
    expect(el.style.opacity).toBe("0.5");
  });

  it("background color -> rgba", () => {
    const el = document.createElement("div");
    applyStyleProperty(el, PROP_BACKGROUND_COLOR, 0x80ff0000);
    expect(el.style.backgroundColor).toBe("rgba(255,0,0,0.502)");
  });

  it("width FILL -> 100%, HUG -> fit-content, fixed -> px", () => {
    expect(sizeCss(bitsFromF32(-1))).toBe("100%");
    expect(sizeCss(bitsFromF32(-2))).toBe("fit-content");
    expect(sizeCss(bitsFromF32(320))).toBe("320px");
  });

  it("alignment maps the protocol enum to CSS", () => {
    expect(alignmentCss(ALIGN_LEADING)).toBe("flex-start");
    expect(alignmentCss(ALIGN_CENTER)).toBe("center");
    expect(alignmentCss(ALIGN_TRAILING)).toBe("flex-end");
  });

  it("disabled toggles native controls + aria-disabled on other elements", () => {
    const button = document.createElement("button");
    applyEnabled(button, 0);
    expect(button.disabled).toBe(true);
    const div = document.createElement("div");
    applyEnabled(div, 0);
    expect(div.getAttribute("aria-disabled")).toBe("true");
    applyEnabled(div, 1);
    expect(div.hasAttribute("aria-disabled")).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { Transport } from "../src/transport";
import {
  CAT_STYLE,
  CMD_SET_TEXT,
  HEADER_SIZE,
  MAGIC,
  OPCODE_SIZE,
  VERSION,
} from "../src/constants";
import type { DomRenderer } from "../src/apply";

/** Minimal fake WebSocket for transport tests. */
class FakeSocket {
  static instances: FakeSocket[] = [];
  readyState = WebSocket.CONNECTING;
  binaryType = "";
  onopen: (() => void) | null = null;
  onmessage: ((event: { data: unknown }) => void) | null = null;
  onclose: (() => void) | null = null;
  onerror: (() => void) | null = null;
  readonly sent: Uint8Array[] = [];
  constructor(readonly url: string) {
    FakeSocket.instances.push(this);
  }
  send(data: Uint8Array): void {
    this.sent.push(data);
  }
  close(): void {
    this.readyState = WebSocket.CLOSED;
    this.onclose?.();
  }
  emitOpen(): void {
    this.readyState = WebSocket.OPEN;
    this.onopen?.();
  }
  emitMessage(data: unknown): void {
    this.onmessage?.({ data });
  }
}

function fakeFactory(url: string): WebSocket {
  return new FakeSocket(url) as unknown as WebSocket;
}

function applyBatchHeader(batch: Uint8Array, opcodeCount: number): void {
  const view = new DataView(batch.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(12, opcodeCount, true);
}

describe("Transport", () => {
  it("applies batches received over the socket", () => {
    const renderer: DomRenderer = { byId: new Map() };
    const span = document.createElement("span");
    renderer.byId.set(1, span);
    const transport = new Transport({ url: "ws://host/ws", renderer, createSocket: fakeFactory });
    transport.start();
    const socket = FakeSocket.instances[0]!;
    socket.emitOpen();

    const batch = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
    applyBatchHeader(batch, 1);
    const view = new DataView(batch.buffer);
    view.setUint8(HEADER_SIZE, CAT_STYLE);
    view.setUint8(HEADER_SIZE + 1, CMD_SET_TEXT);
    view.setUint32(HEADER_SIZE + 4, 1, true);
    view.setUint32(HEADER_SIZE + 8, 0, true);
    socket.emitMessage(batch);
    expect(span.textContent).toBe("");

    transport.stop();
  });

  it("ignores malformed batches without throwing", () => {
    const transport = new Transport({
      url: "ws://host/ws",
      renderer: { byId: new Map() },
      createSocket: fakeFactory,
    });
    transport.start();
    const socket = FakeSocket.instances[0]!;
    expect(() => socket.emitMessage(new Uint8Array(4))).not.toThrow();
    transport.stop();
  });

  it("reconnects after the socket closes", async () => {
    const transport = new Transport({
      url: "ws://host/ws",
      renderer: { byId: new Map() },
      createSocket: fakeFactory,
    });
    transport.start();
    expect(FakeSocket.instances).toHaveLength(1);
    FakeSocket.instances[0]!.close();
    await new Promise((resolve) => setTimeout(resolve, 700));
    expect(FakeSocket.instances.length).toBeGreaterThanOrEqual(2);
    transport.stop();
  });

  it("reports open status and sends encoded bytes", () => {
    const statuses: string[] = [];
    const renderer: DomRenderer = { byId: new Map() };
    const transport = new Transport({
      url: "ws://host/ws",
      renderer,
      createSocket: fakeFactory,
      onStatus: (status) => statuses.push(status),
    });
    transport.start();
    FakeSocket.instances[0]!.emitOpen();
    expect(statuses).toEqual(["open"]);
    transport.send(new Uint8Array([1, 2, 3]));
    expect(FakeSocket.instances[0]!.sent).toHaveLength(1);
    transport.stop();
  });
});

