/* ===== Inter (SIL OFL) ===== */
@font-face { font-family: 'Inter'; font-style: normal; font-weight: 400; font-display: swap; src: url(data:font/woff2;base64,__INTER_REGULAR__) format('woff2'); }
@font-face { font-family: 'Inter'; font-style: normal; font-weight: 600; font-display: swap; src: url(data:font/woff2;base64,__INTER_SEMIBOLD__) format('woff2'); }

/* ===== Design tokens (protocol retheme via SET_DESIGN_TOKEN) ===== */
:root {
  --pl-color-accent: #2563eb;
  --pl-color-surface: #ffffff;
