/// The rendered `style="…"` for a node — no Tailwind classes; everything inline.
fn style_attr(&self) -> String {
    let css = format!("{}{}", self.style_css(), self.border_style());
    if css.is_empty() {
        String::new()
    } else {
        format!(" style=\"{css}\"")
    }
}

